source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            top = min(y for y, x in cells); bottom = max(y for y, x in cells)
            left = min(x for y, x in cells); right = max(x for y, x in cells)
            if bottom-top < 2 or right-left < 2:
                continue
            border = all(grid[y][x] == color for y in range(top,bottom+1) for x in range(left,right+1) if y in (top,bottom) or x in (left,right))
            interior_empty = all(grid[y][x] == background for y in range(top+1,bottom) for x in range(left+1,right))
            if border and interior_empty:
                fill = 7 if (bottom-top+1) % 2 else 2
                for y in range(top+1,bottom):
                    for x in range(left+1,right):
                        out[y][x] = fill
    return out
'''
